// Word game: a daily five-letter word game (Dutch) for PaperOS. Game logic only, platform-free; the screens are in
// wordgame_app.cpp, the words in words_data.cpp (generated by tools/gen-wordgame-words.py). docs/apps/wordgame.md.
//
// One word a day, six tries. A guess must be a known word; every letter of a guess is marked: right place, in the word at
// another place, or not in the word. The day is the device's local date; nothing comes from a server.
#pragma once

#include <array>
#include <climits>
#include <cstdint>
#include <string>
#include <vector>

namespace pos::wordgame {

constexpr int kLen = 5;
constexpr int kTries = 6;
constexpr const char* kName = "Woordle";  // the title, and the first word of a shared score

// Marks of one letter of a guess. The characters are also what the store keeps.
constexpr char kRight = 'c';   // right place
constexpr char kOther = 'p';   // in the word, at another place
constexpr char kAbsent = 'a';  // not in the word (or no more of them)
constexpr char kUnused = ' ';  // a key that was not tried yet

// "No day". An int on purpose: INT32_MIN is a long on the ESP32, and Store::get has no overload for long.
constexpr int kNoDay = INT_MIN;

struct Date {
  int year = 0, month = 0, day = 0;
};

// Whole days from the first puzzle (2026-11-16 = day 0) to `date`; negative before it.
int dayOf(const Date& date);
// The number shown and shared: day 0 is puzzle 1.
int puzzleNumber(int day);
// The word of that day. The list wraps (and runs backwards for days before the first puzzle).
std::string answerOf(int day);

int answerCount();
int wordCount();
// True if `word` (lowercase, five letters) may be played as a guess.
bool isWord(const std::string& word);

// The marks of `guess` against `answer`, one character per letter. A letter that is in the answer once is marked once:
// right places first, then other places from left to right while the answer has that letter left.
std::string marksOf(const std::string& answer, const std::string& guess);
// The best mark each letter a-z got in `guesses` (right > other > absent), kUnused if it was not played.
std::array<char, 26> keyMarks(const std::string& answer, const std::vector<std::string>& guesses);

bool solved(const std::string& answer, const std::vector<std::string>& guesses);
bool finished(const std::string& answer, const std::vector<std::string>& guesses);

// The score as text for a chat: "<kName> 12 4/6", an empty line, one line of squares per guess (X/6 when not guessed).
std::string shareText(int number, const std::string& answer, const std::vector<std::string>& guesses);

// What was played so far. `streak` counts days won in a row and is only valid on `lastWonDay` and the day after.
struct Stats {
  int played = 0;
  int won = 0;
  int streak = 0;
  int maxStreak = 0;
  int lastWonDay = kNoDay;
  std::array<int, kTries> turns{};  // games won in 1..6 tries
};
// Adds the finished game of `day` (call once per day).
void record(Stats& stats, int day, bool won, int tries);
// The streak as it stands on `today`: 0 once a day was missed or lost.
int streakOn(const Stats& stats, int today);
int winPercent(const Stats& stats);

// --- More accepted words, fetched now and then (docs/apps/wordgame.md "Fetched words") ----------------------------------------

// A plain text file: one lowercase five-letter word per line, two parts split by one empty line. Only the second part is
// used (words accepted as a guess); the first part is another game's words of the day and is not read.
constexpr const char* kListUrl = "https://woordscore.nl/woordlijst.txt";
constexpr int64_t kListMaxAgeS = 7 * 86400;  // fetched again after a week
constexpr int64_t kListRetryS = 86400;       // after a failed try: not before a day later
constexpr size_t kListMaxBytes = 200 * 1024;
constexpr size_t kListMaxWords = 12000;

// The second part of the list file as packed words: sorted, each once, five letters a-z each, no separators. Lines that are
// not such a word are skipped. "" if the text has no second part.
std::string packGuessList(const std::string& text);
// True if `packed` is what packGuessList gives (a cache file that was cut or damaged is not).
bool validPacked(const std::string& packed);
bool inPacked(const std::string& packed, const std::string& word);
// Whether to fetch the list now. Times in Unix seconds, 0 = never. With the clock not set (`now` too small to be a date):
// only if the list was never fetched.
bool listDue(int64_t now, int64_t fetchedAt, int64_t triedAt);

namespace data {
extern const int kWordCount;
extern const char kWords[];
extern const int kAnswerCount;
extern const uint16_t kAnswers[];
}  // namespace data

}  // namespace pos::wordgame
